# /// script
# [tool.databricks.environment]
# environment_version = "5"
# ///
# MAGIC %md
# MAGIC Notebook temporário: gera `random_forest_prep_rev1` a partir do `random_forest_prep_rev0` (que não é alterado). Pode ser apagado depois.

# COMMAND ----------

import base64, json
from databricks.sdk import WorkspaceClient
from databricks.sdk.service.workspace import ExportFormat, ImportFormat, Language

NEW = json.loads(base64.b64decode("").decode("utf-8"))
w = WorkspaceClient()
me = w.current_user.me().user_name

def achar(nome, raizes, prof=4):
    for raiz in raizes:
        pilha = [(raiz, 0)]
        while pilha:
            p, d = pilha.pop()
            try:
                itens = list(w.workspace.list(p))
            except Exception:
                continue
            for it in itens:
                if it.path.rsplit('/', 1)[-1] == nome and str(it.object_type).endswith('NOTEBOOK'):
                    return it.path
                if str(it.object_type).endswith('DIRECTORY') and d < prof:
                    pilha.append((it.path, d + 1))
    return None

src_path = achar('random_forest_prep_rev0', ['/Previsao de consumo de vapor', f'/Users/{me}', '/'])
assert src_path, 'random_forest_prep_rev0 não encontrado'
dst_path = src_path.rsplit('/', 1)[0] + '/random_forest_prep_rev1'
print('Origem :', src_path)
print('Destino:', dst_path)

raw = base64.b64decode(w.workspace.export(src_path, format=ExportFormat.SOURCE).content).decode('utf-8')
HEADER = '# Databricks notebook source'
SEP = '# COMMAND ----------'
assert raw.startswith(HEADER)
cells = [c.strip('\n') for c in raw[len(HEADER):].split(SEP)]
print('Células no rev0:', len(cells))
MARK = {5: 'CLIMA_PATH', 9: 'CORRELAÇÃO DAS FEATURES COM CADA TARGET', 11: 'DEFINIÇÃO DO TARGET',
        12: 'FEATURE ENGINEERING TEMPORAL', 13: 'PREPARAÇÃO FINAL', 14: 'SALVAR TABELA PREPARADA',
        15: 'FEATURE IMPORTANCE'}
assert len(cells) == 15, f'esperado 15 células, achei {len(cells)}'
for i, m in MARK.items():
    assert m in cells[i - 1], f'célula {i} não contém "{m}"'

def titulo(c):
    ls = [l for l in c.split('\n') if l.startswith('# DBTITLE')]
    return ls[0] + '\n' if ls else ''

def rep(i, k):
    return titulo(cells[i - 1]) + NEW[k]

out = [cells[0], cells[1], NEW['md_rev1'], NEW['config'], cells[2], cells[3], rep(5, 'merge'),
       cells[5], cells[6], cells[7], rep(9, 'pearson'), cells[9], rep(11, 'target'), rep(12, 'fe'),
       rep(13, 'prep'), cells[13], rep(15, 'rf'), NEW['plot'], NEW['comparacao'], NEW['consolidacao']]
content = HEADER + '\n' + ('\n\n' + SEP + '\n\n').join(out) + '\n'
w.workspace.import_(dst_path, content=base64.b64encode(content.encode('utf-8')).decode(),
                    format=ImportFormat.SOURCE, language=Language.PYTHON, overwrite=False)
print(f'OK: {dst_path} criado com {len(out)} células (rev0 não foi alterado).')